32	// The file a tool is about to write, repo-relative with forward slashes — or null
33	// when the tool names no file or the file is outside the project (nothing here
34	// scopes a path the repo does not own).
35	function targetPath(payload, projectRoot) {
36	  const input = payload.tool_input ?? {};
37	  const raw = payload.tool_name === 'NotebookEdit' ? input.notebook_path : input.file_path;
38	  if (typeof raw !== 'string' || !raw) return null;
39	  const abs = isAbsolute(raw) ? raw : resolve(projectRoot, raw);
40	  const rel = relative(projectRoot, abs);
41	  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return null;
42	  return rel.split(sep).join('/');
43	}
